export default function BrandIcon({ glyph = 'home', className = '' }) {
  const icon = glyphs[glyph]
  if (!icon) return null

  return (
    <svg
      className={`brand-icon-glyph ${className}`}
      width="24"
      height="24"
      viewBox={`0 0 24 24`}
      fill="none"
      aria-hidden="true"
    >
      <g transform={`translate(${(24 - parseFloat(icon.viewBox.split(' ')[2])) / 2}, ${(24 - parseFloat(icon.viewBox.split(' ')[3])) / 2})`}>
        {icon.path}
      </g>
    </svg>
  )
}

BrandIcon.glyphs = Object.keys(glyphs)
